a.navbar-brand {
  white-space: normal;
  text-align: center;
  word-break: break-all;
}

/* Provide sufficient contrast against white background */
a {
  color: #0366d6;
}

.btn-primary {
  color: #fff;
  background-color: #1b6ec2;
  border-color: #1861ac;
}

.nav-pills .nav-link.active, .nav-pills .show > .nav-link {
  color: #fff;
  background-color: #1b6ec2;
  border-color: #1861ac;
}

/* Sticky footer styles
-------------------------------------------------- */
html {
  font-size: 14px;
  position: relative;
  height: 100%;
}

@media (min-width: 768px) {
  html {
    font-size: 16px;
  }
}
.border-top {
  border-top: 1px solid #e5e5e5;
}

.border-bottom {
  border-bottom: 1px solid #e5e5e5;
}

.box-shadow {
  box-shadow: 0 0.25rem 0.75rem rgba(0, 0, 0, 0.05);
}

button.accept-policy {
  font-size: 1rem;
  line-height: inherit;
}

/* Sticky footer styles
-------------------------------------------------- */
body {
  height: 100%;
  overflow-y: hidden;
}

.warning-message {
  width: 100%;
  height: 48px;
  background-color: #DB2E2E;
  text-align: center;
  color: #FFFFFF;
  padding-top: 7px;
  padding-bottom: 7px;
}
.warning-message label {
  margin-bottom: 0px;
  word-wrap: break-word;
  margin: 4px ​15px 0px 15px;
}
.warning-message button.update-plan {
  border: 2px solid #FFFFFF;
  border-radius: 16px;
  color: #FFFFFF;
  font-weight: 700;
  padding: 2px 10px 4px 10px;
  margin-left: 5px;
  margin-right: 30px;
}
.warning-message .blazored-modal-close {
  position: absolute;
  right: 21px;
  top: 5px;
}
.warning-message .blazored-modal-close span {
  color: #FFFFFF;
}

.page-frame {
  height: 100%;
  margin: 0;
}

/* =====================================================
    Footer styling
===================================================== */
.footer {
  width: 100%;
  white-space: nowrap;
  line-height: 34px;
  margin-left: -15px;
  background-color: #EFEFEF;
}

.footer-row {
  margin-left: 15px;
  margin-right: 10px;
  float: right;
}

.footer-logo {
  float: left;
  margin-right: 20px;
  margin-top: 13px;
  height: 11px;
}

.footer-nav {
  float: left;
  margin: 0;
  padding-left: 20px;
  list-style: none;
}

.footer-nav-item {
  display: inline-block;
  margin: 0;
  padding: 0 5px;
  font-size: 0.7em;
  line-height: 0.7em;
}

a.footer-navlink {
  text-decoration: underline;
  color: #444444;
}

.footer-copyright {
  text-align: right;
  color: #444444;
  font-size: 0.7em;
  padding-top: 1px;
}

@media (max-width: 991px) {
  .footer-copyright {
    display: none;
  }
}
/* =====================================================
    Main content styling
===================================================== */
.main-content {
  background-color: #fff;
}

/* Scroll Top Top */
.scroll-to-top {
  padding: 1px;
  text-align: center;
  position: fixed;
  bottom: 10px;
  z-index: 10001;
  display: none;
  right: 30px;
}

.scroll-to-top > i {
  display: inline-block;
  color: #687991;
  font-size: 30px;
  opacity: 0.6;
  filter: alpha(opacity=60);
}

.scroll-to-top:hover {
  cursor: pointer;
}

.scroll-to-top:hover > i {
  opacity: 1;
  filter: alpha(opacity=100);
}

