/* =====================================================
    Error page styles
===================================================== */
html, body {
  font-family: "Delivery", sans-serif, Helvetica, Arial, sans-serif;
}

a, .btn-link {
  color: #0366d6;
}

.btn-primary {
  color: #fff;
  background-color: #1b6ec2;
  border-color: #1861ac;
}

.main-app {
  position: relative;
  display: flex;
  flex-direction: row;
}

.top-row {
  height: 3.5rem;
  display: flex;
  align-items: center;
}

.page {
  position: relative;
  display: flex;
  flex-direction: column;
  padding-top: 0.5rem;
}

.main {
  flex: 1;
}

.main .top-row {
  background-color: #f7f7f7;
  border-bottom: 1px solid #d6d5d5;
  justify-content: flex-end;
}

.main .top-row > a, .main .top-row .btn-link {
  white-space: nowrap;
  margin-left: 1.5rem;
}

.main .top-row a:first-child {
  overflow: hidden;
  text-overflow: ellipsis;
}

.sidebar {
  background-image: linear-gradient(180deg, rgb(5, 39, 103) 0%, #3a0647 70%);
}

.sidebar .top-row {
  background-color: rgba(0, 0, 0, 0.4);
}

.sidebar .navbar-brand {
  font-size: 1.1rem;
}

.sidebar .oi {
  width: 2rem;
  font-size: 1.1rem;
  vertical-align: text-top;
  top: -2px;
}

.sidebar .nav-item {
  font-size: 0.9rem;
  padding-bottom: 0.5rem;
}

.sidebar .nav-item:first-of-type {
  padding-top: 1rem;
}

.sidebar .nav-item:last-of-type {
  padding-bottom: 1rem;
}

.sidebar .nav-item a {
  color: #d7d7d7;
  border-radius: 4px;
  height: 3rem;
  display: flex;
  align-items: center;
  line-height: 3rem;
}

.sidebar .nav-item a.active {
  background-color: rgba(255, 255, 255, 0.25);
  color: white;
}

.sidebar .nav-item a:hover {
  background-color: rgba(255, 255, 255, 0.1);
  color: white;
}

.content {
  padding-top: 1.1rem;
}

.navbar-toggler {
  background-color: rgba(255, 255, 255, 0.1);
}

.valid.modified:not([type=checkbox]) {
  outline: 1px solid #26b050;
}

.invalid {
  outline: 1px solid red;
}

.validation-message {
  color: red;
}

#blazor-error-ui, #blazor-error-ui-error-page {
  background: #FFFFFF;
  height: 100%;
  width: 100%;
  bottom: 0;
  display: none;
  left: 0;
  position: fixed;
  z-index: 1000;
}

#blazor-error-ui-error-page {
  display: block;
}

#blazor-error-ui .dismiss, #blazor-error-ui-error-page .dismiss {
  cursor: pointer;
  position: absolute;
  right: 0.75rem;
  top: 0.5rem;
}

#blazor-error-ui .banner, #blazor-error-ui-error-page .banner {
  height: 80px;
  margin-bottom: 100px;
  background: #FFCC00;
}

#blazor-error-ui .bannerLogo, #blazor-error-ui-error-page .bannerLogo {
  width: 120px;
  height: 80px;
  margin-left: 46px;
  margin-top: 0;
  position: absolute;
  background-image: url("../../../../_content/Starshipit.Blazor.Shared/static/assets/images/DHL_Logo.png");
  background-repeat: no-repeat;
  top: 20px;
}

#blazor-error-ui .container, #blazor-error-ui-error-page .container {
  font-family: "Delivery-Bold", sans-serif, sans-serif;
  text-align: center;
  max-width: 620px;
}

#blazor-error-ui .header1, #blazor-error-ui-error-page .header1 {
  color: #D40511;
  font-size: 60px;
  font-weight: 700;
}

#blazor-error-ui .header2, #blazor-error-ui-error-page .header2 {
  color: #333333;
  font-size: 30px;
  margin-bottom: 15px;
  margin-top: 5px;
  font-weight: 700;
}

#blazor-error-ui .detail, #blazor-error-ui-error-page .detail {
  color: #333333;
  font-family: "Delivery", sans-serif;
  font-size: 20px;
  width: 476px;
  margin-left: 56px;
}

#blazor-error-ui .detail .a, #blazor-error-ui-error-page .detail .a {
  color: #D40511;
  margin-left: 0px;
}
#blazor-error-ui .detail .a.site1-link, #blazor-error-ui-error-page .detail .a.site1-link {
  display: none;
}
#blazor-error-ui .detail .a.site2-link, #blazor-error-ui-error-page .detail .a.site2-link {
  margin-left: 0;
  display: inline;
}
#blazor-error-ui .detail .a.site3-link, #blazor-error-ui-error-page .detail .a.site3-link {
  display: none;
}
#blazor-error-ui .detail .a.site4-link, #blazor-error-ui-error-page .detail .a.site4-link {
  display: none;
}

#blazor-error-ui .returnHomeButton, #blazor-error-ui-error-page .returnHomeButton {
  font-family: "Delivery-Bold", sans-serif !important;
  font-weight: 700 !important;
  width: 177px;
  height: 49px;
  background: #D40511;
  border: solid 1px #D40511;
  outline: none;
  border-radius: 5px;
  opacity: 1;
  font-size: 20px;
  color: #FFFFFF;
  margin-top: 40px;
}
@-moz-document url-prefix() {
  #blazor-error-ui .returnHomeButton, #blazor-error-ui-error-page .returnHomeButton {
    font-weight: normal !important;
  }
}
#blazor-error-ui .returnHomeButton:hover, #blazor-error-ui .returnHomeButton:focus, #blazor-error-ui-error-page .returnHomeButton:hover, #blazor-error-ui-error-page .returnHomeButton:focus {
  color: #FFFFFF;
  opacity: 1;
  outline: none;
  box-shadow: none;
}
#blazor-error-ui .returnHomeButton:hover, #blazor-error-ui-error-page .returnHomeButton:hover {
  background-color: #121212;
  border-color: #121212;
}
#blazor-error-ui .returnHomeButton:focus, #blazor-error-ui-error-page .returnHomeButton:focus {
  background-color: #2D2D2D;
  border-color: #2D2D2D;
