.left-pane {
  display: flex;
  flex-direction: column;
  position: relative;
  background: #2d2d2d;
  width: 230px;
  height: 100%;
  min-height: 100svh;
  z-index: 1;
  border-right: solid 1px #2d2d2d;
  overflow: hidden;
  padding: 20px 0 0 0;
  --left-pane-inline-padding: 20px;
}
.left-pane a, .left-pane div {
  display: block;
}

.left-pane-closed {
  display: flex;
  flex-direction: column;
  position: relative;
  padding: 20px;
  background: #2d2d2d;
  width: 70px;
  min-height: 100svh;
  z-index: 1;
  border-right: solid 1px #2d2d2d;
}
.left-pane-closed a, .left-pane-closed div {
  display: block;
}

.ssi-display {
  overflow: hidden;
  position: relative;
}
.ssi-display .nav-section {
  container-type: inline-size;
  container-name: nav-section;
  display: grid;
  grid-template-rows: 1fr;
  position: relative;
  flex-grow: 1;
  overflow-x: hidden;
}
.ssi-display .nav-section .ui-toggle-label {
  cursor: pointer;
  display: flex;
  align-items: center;
  gap: 10px;
  width: 100%;
  height: 36px;
  margin: 0;
  padding-inline: var(--left-pane-inline-padding);
  background-color: #E7F1FE;
}
@container nav-section (width < 150px) {
  .ssi-display .nav-section .ui-toggle-label {
    background-color: inherit;
  }
  .ssi-display .nav-section .ui-toggle-label .ui-toggle-text {
    display: none;
  }
}
.ssi-display .nav-section .ui-toggle-label .ui-toggle {
  --toggle-width: 25px;
  --inactive-colour: #E8E8E8;
  background-color: var(--inactive-colour);
  position: relative;
  display: inline-block;
  width: var(--toggle-width);
  height: 14px;
  border-radius: 7px !important;
  cursor: pointer;
  margin: 0;
  flex-shrink: 0;
}
.ssi-display .nav-section .ui-toggle-label .ui-toggle::before {
  position: absolute;
  content: "";
  aspect-ratio: 1;
  height: 100%;
  border: 1px solid var(--inactive-colour);
  background-color: white;
  border-radius: 50%;
  transition: translate 0.3s ease;
}
.ssi-display .nav-section .ui-toggle-label .ui-toggle:has(input:checked) {
  background-color: #007BFF;
}
.ssi-display .nav-section .ui-toggle-label .ui-toggle:has(input:checked)::before {
  translate: calc(var(--toggle-width) - 100%) 0;
  border: 1px solid #007BFF;
}
.ssi-display .content-section {
  display: grid;
  grid-template-rows: 1fr;
  grid-auto-rows: min-content;
  position: relative;
  flex: 1 0 calc(100vw - 230px);
  width: auto;
  height: 100vh;
}
.ssi-display .content-section.wide {
  flex: 1 0 calc(100vw - 70px);
}
.ssi-display .ssi-page-header {
  display: flex;
  border-right: solid 1px #C1C1C1;
  width: 230px;
  margin-left: 0;
}
.ssi-display.no-menu .left-pane {
  flex: 0 0 0;
  width: 0;
  display: none;
}
.ssi-display.no-menu .content-section {
  flex: 0 0 100%;
  width: auto;
}
.ssi-display.no-menu .ssi-page-header {
  display: none;
}

