.grid-container {
  position: relative;
}
.grid-container div.ssit-alt-grid table td,
.grid-container div.ssit-alt-grid table th {
  border: 0;
}
.grid-container .ssit-alt-grid .k-grid-pager {
  border-color: #B8B8B8 !important;
  border-width: 1px 1px 1px;
  width: 99.9%;
}
.grid-container .ssit-alt-grid .k-grid-table {
  border-collapse: collapse;
}
.grid-container .ssit-alt-grid .k-grid-table tr {
  border: solid 1px #B8B8B8;
}
.grid-container .ssit-alt-grid .k-grid-content {
  color: #2D2D2D;
  overflow: auto;
}
.grid-container .ssit-alt-grid .k-grid-table .k-master-row {
  background-color: #fff;
}
.grid-container .ssit-alt-grid .k-grid-table .k-master-row:hover, .grid-container .ssit-alt-grid .k-grid-table .k-master-row:hover td.sorted {
  background-color: #EFEFEF;
}
.grid-container .ssit-alt-grid .k-grid-table .k-master-row.k-alt {
  background-color: #F5F5F5;
}
.grid-container .ssit-alt-grid .k-grid-table .k-master-row.k-alt:hover {
  background-color: #EFEFEF;
}
.grid-container .ssit-alt-grid .k-grid-header .k-header > .k-link, .grid-container .ssit-alt-grid .k-grid-header .k-header {
  font-family: "Delivery-Bold", sans-serif !important;
  font-weight: 700 !important;
  font-size: 13px !important;
  line-height: 1.2 !important;
  letter-spacing: 1px !important;
  color: #2D2D2D;
  text-transform: uppercase;
}
@-moz-document url-prefix() {
  .grid-container .ssit-alt-grid .k-grid-header .k-header > .k-link, .grid-container .ssit-alt-grid .k-grid-header .k-header {
