===================================================== */
.ssit-dropdown-container {
  position: relative;
}
.ssit-dropdown-container.print-button-container {
  display: inline-flex;
  height: 30px;
}
.ssit-dropdown-container.print-button-container .k-animation-container {
  translate: -100% calc(-100% - 5px);
  right: 0;
  width: fit-content;
}
.ssit-dropdown-container.print-button-container .k-animation-container li {
  white-space: nowrap;
  padding-inline: 10px;
}

.ssit-dropdown-list {
  position: absolute;
}
.ssit-dropdown-list .k-animation-container {
  min-width: 200px;
}
.ssit-dropdown-list.detail-info .ssit-dropdown {
  width: 100%;
  padding: 15px;
  margin-right: 12px;
  background-color: #EFEFEF;
}
.ssit-dropdown-list.detail-info .ssit-dropdown ul {
  margin-bottom: 0;
  padding-left: 0;
}
.ssit-dropdown-list.detail-info .ssit-dropdown ul li {
  font-size: 12px;
  color: #2D2D2D;
  word-wrap: break-word;
}

.ssit-dropdown-click-btn,
.ssit-dropdown-click-btn:focus {
  border-right: none;
  text-overflow: ellipsis;
  white-space: nowrap;
  border: 1px solid #B8B8B8;
  border-top-left-radius: 4px;
  border-bottom-left-radius: 4px;
  padding: 3px 8px 2px 10px;
  outline: none;
  height: 39px;
}
.ssit-dropdown-click-btn.order-action-drop-down-button,
.ssit-dropdown-click-btn:focus.order-action-drop-down-button {
  padding: 7px 5px 7px 20px;
  text-transform: uppercase;
  white-space: nowrap;
  font-size: 12px;
  letter-spacing: 0.36px;
  line-height: 17px;
  display: inline-flex;
  align-items: center;
  background-color: #007C39;
  color: #fff;
  border-radius: 4px;
  border-color: #007C39;
  font-family: "Delivery-Bold", sans-serif !important;
  font-weight: 700 !important;
  height: 30px;
  border-top-right-radius: 0px;
  border-bottom-right-radius: 0px;
}
.ssit-dropdown-click-btn.order-action-drop-down-button i,
.ssit-dropdown-click-btn:focus.order-action-drop-down-button i {
  color: #fff;
}
.ssit-dropdown-click-btn.order-action-drop-down-button:hover, .ssit-dropdown-click-btn.order-action-drop-down-button:focus,
.ssit-dropdown-click-btn:focus.order-action-drop-down-button:hover,
.ssit-dropdown-click-btn:focus.order-action-drop-down-button:focus {
  background-color: #007C39;
  color: #fff;
  outline: none;
  box-shadow: none;
  border-color: #007C39;
}
.ssit-dropdown-click-btn.order-action-drop-down-button:hover i, .ssit-dropdown-click-btn.order-action-drop-down-button:focus i,
.ssit-dropdown-click-btn:focus.order-action-drop-down-button:hover i,
.ssit-dropdown-click-btn:focus.order-action-drop-down-button:focus i {
  color: #fff;
}
@-moz-document url-prefix() {
  .ssit-dropdown-click-btn.order-action-drop-down-button,
  .ssit-dropdown-click-btn:focus.order-action-drop-down-button {
    font-weight: normal !important;
  }
}
.ssit-dropdown-click-btn.order-action-drop-down-button i,
.ssit-dropdown-click-btn:focus.order-action-drop-down-button i {
  font-size: 10px;
}

.ssit-dropdown-select-btn,
.ssit-dropdown-select-btn:focus {
  border-left: none;
  box-sizing: unset;
  outline: none;
  border-top: solid 1px #B8B8B8;
  border-right: solid 1px #B8B8B8;
  border-bottom: solid 1px #B8B8B8;
  border-radius: 0px 4px 4px 0px;
  padding: 3px 6px 2px 15px;
  height: 32px;
}
.ssit-dropdown-select-btn.order-action-drop-down-chevron.order-action-drop-down-chevron,
.ssit-dropdown-select-btn:focus.order-action-drop-down-chevron.order-action-drop-down-chevron {
  background-color: #007C39 !important;
  border-color: #007C39 !important;
  color: #FFF !important;
  border-radius: 0 4px 4px 0 !important;
  height: 30px;
  padding: 0px 10px;
  display: flex;
  align-items: center;
  border: none;
}
.ssit-dropdown-select-btn.order-action-drop-down-chevron.order-action-drop-down-chevron i,
.ssit-dropdown-select-btn:focus.order-action-drop-down-chevron.order-action-drop-down-chevron i {
  color: inherit !important;
}
.ssit-dropdown-select-btn.order-action-drop-down-chevron.order-action-drop-down-chevron:hover, .ssit-dropdown-select-btn.order-action-drop-down-chevron.order-action-drop-down-chevron :focus,
.ssit-dropdown-select-btn:focus.order-action-drop-down-chevron.order-action-drop-down-chevron:hover,
