  background-color: #007C39 !important;
  border-color: #007C39 !important;
  color: #FFF !important;
  border: none;
}

.ssit-dropdown {
  border-radius: 4px !important;
  box-shadow: 0 2px 4px 0 rgba(0, 0, 0, 0.5);
  border: solid 1px #cacaca;
}
.ssit-dropdown ul {
  padding-left: 0px;
  padding-top: 10px;
}
.ssit-dropdown li {
  padding-left: 10px;
  list-style-type: none;
}
.ssit-dropdown li a {
  text-decoration: none;
  color: #161616;
}
.ssit-dropdown li a:hover {
  text-decoration: none;
}
.ssit-dropdown li:hover {
  background-color: #EFEFEF;
}
.ssit-dropdown.ssit-filter-view {
  max-height: 650px;
  overflow-y: auto;
  overflow-x: hidden;
  width: 230px;
  max-height: 50vh;
}
.ssit-dropdown.ssit-filter-view ul {
  max-height: 600px;
  overflow-y: auto;
  overflow-x: hidden;
  margin-bottom: 0;
  width: 230px;
}
.ssit-dropdown.ssit-filter-view ul li:first-child:hover {
  background-color: #FFF;
}
.ssit-dropdown.ssit-filter-view li {
  padding: 0 0 1px 10px;
}
.ssit-dropdown.ssit-filter-view .filter-view-col-description {
  padding: 0px 0px 0px 10px;
}
.ssit-dropdown.ssit-filter-view .filter-view-search {
  margin-bottom: 8px;
  width: 95%;
  height: 30px;
}
.ssit-dropdown.ssit-filter-view .filter-view-search:focus {
  box-shadow: none;
  border: 1px solid #ced4da;
}

.title-search-container {
  display: flex;
  height: 40px;
  text-align: right;
}
.title-search-container.search-expanded {
  margin-left: auto;
}
.title-search-container .ssit-titlebar-search {
  border: solid 1px #C1C1C1;
  font-weight: normal;
  color: #202020;
  font-size: 15px;
  overflow: hidden;
  border-radius: 4px;
  display: flex;
  height: 40px;
}
.title-search-container .ssit-titlebar-search .ssit-order-search-table {
  padding-left: 10px;
  background-color: #fff;
  display: flex;
  border-radius: 4px;
}
.title-search-container .ssit-titlebar-search:focus {
  outline: none;
}
.title-search-container .ssit-user-menu {
  padding: 0 3px;
  width: 220px;
  position: relative;
}
.title-search-container .ssit-user-menu .user-profile-dropdown {
  background-color: #161616;
  color: #B8B8B8;
  font-size: 12px;
  scale: 1 0;
  translate: 0 100%;
  transition: scale 0.2s ease-in-out;
  transform-origin: top;
  position: absolute;
  right: 0;
  bottom: -3px;
  width: 215px;
  text-align: left;
  z-index: 1000;
}
.title-search-container .ssit-user-menu .user-profile-dropdown.showing {
  scale: 1;
}
.title-search-container .ssit-user-menu .user-profile-dropdown .profile-menu-rule {
  border-top: 1px solid #C1C1C1;
  margin-top: 10px;
  margin-bottom: 10px;
