/* =====================================================
    Custom dropdown component so we can do caret styling
===================================================== */
.dropdown-container-select {
  position: relative;
  display: inline-block;
  background: white;
}

.dropdown-container-select::after {
  position: absolute;
  top: 10px;
  right: 20px;
  width: 0;
  height: 0;
  color: #d40511;
  font-family: "Font Awesome 5 Free", sans-serif;
  font-weight: 700;
  font-size: 10px;
  content: "\f078";
  pointer-events: none;
}

.open.dropdown-container-select::after {
  content: "\f077";
}

.dropdown-container-select select {
  appearance: none;
  -webkit-appearance: none;
  background: transparent;
  cursor: pointer;
  padding-left: 10px;
  padding-top: 3px;
}

.dropdown-select {
  width: 150px;
  height: 34px;
  border: solid 1px #B7B7B7;
  border-radius: 2px;
}
.dropdown-select:focus, .dropdown-select:active {
  outline: none;
  border: solid 1px #B7B7B7;
}

