.warehouse-management-page .page-main-content.wms-marketing {
  padding: 0;
  overflow-y: auto;
  background-color: #f7f7f7;
}

/* ── Badge ──────────────────────────────────────────── */
.wms-badge {
  display: inline-block;
  padding: 3px 10px;
  font-family: "Delivery", sans-serif;
  font-size: 11px;
  font-weight: 600;
  border: 1px solid rgba(255, 255, 255, 0.4);
  border-radius: 999px;
  letter-spacing: 0.02em;
  margin-bottom: 8px;
  color: #ffffff;
}

/* ── Buttons ────────────────────────────────────────── */
.wms-btn {
  display: inline-flex;
  align-items: center;
  justify-content: center;
  gap: 6px;
  padding: 8px 18px;
  font-family: "Delivery", sans-serif;
  font-size: 13px;
  font-weight: 600;
  border-radius: 6px;
  cursor: pointer;
  transition: all 0.15s ease;
  text-decoration: none;
  border: none;
  line-height: 1.4;
}
.wms-btn:disabled {
  opacity: 0.5;
  cursor: not-allowed;
}
.wms-btn i {
  font-size: 12px;
}

.wms-btn-sm {
  padding: 6px 14px;
  font-size: 12px;
}

.wms-btn-primary {
  background: #007bff;
  color: #ffffff;
}
.wms-btn-primary:hover:not(:disabled) {
  background: #006ee3;
  color: #ffffff;
  text-decoration: none;
}

.wms-btn-ghost {
  background: transparent;
  color: rgba(255, 255, 255, 0.85);
}
.wms-btn-ghost:hover:not(:disabled) {
  color: #ffffff;
  background: rgba(255, 255, 255, 0.08);
  text-decoration: none;
}

.wms-btn-outline {
  background: transparent;
  color: #333333;
  border: 1px solid #B8B8B8;
}
.wms-btn-outline:hover:not(:disabled) {
  background: #f0f0f0;
  color: #333333;
  text-decoration: none;
}

/* ── Hero (split layout) ───────────────────────────── */
.wms-hero-section {
  background: linear-gradient(135deg, #007bff 0%, #0056b3 100%);
  padding: 28px 28px;
  color: #ffffff;
}

.wms-hero-grid {
  display: grid;
  grid-template-columns: 1fr 1.1fr;
  gap: 28px;
  align-items: center;
}
@media (max-width: 768px) {
  .wms-hero-grid {
    grid-template-columns: 1fr;
  }
}

.wms-hero-copy .wms-hero-title {
  font-family: "Delivery", sans-serif;
  font-size: 24px;
  font-weight: 700;
  margin: 0 0 10px;
  letter-spacing: -0.3px;
  line-height: 1.25;
  color: #ffffff;
}
.wms-hero-copy .wms-hero-subtitle {
  font-family: "Delivery", sans-serif;
  font-size: 13px;
  line-height: 1.6;
  margin: 0 0 14px;
  opacity: 0.9;
  max-width: 400px;
  color: #ffffff;
}

.wms-hero-ctas {
  display: flex;
  align-items: center;
  gap: 8px;
  flex-wrap: wrap;
}

.wms-hero-fine-print {
  margin-top: 8px;
  font-family: "Delivery", sans-serif;
  font-size: 11px;
  opacity: 0.65;
  color: #ffffff;
}

/* Preview */
.wms-hero-preview .wms-preview-image {
  border-radius: 8px;
  overflow: hidden;
  border: 1px solid rgba(255, 255, 255, 0.15);
  background: rgba(255, 255, 255, 0.05);
}
.wms-hero-preview .wms-preview-image video, .wms-hero-preview .wms-preview-image img {
  display: block;
  width: 100%;
  height: auto;
}

.wms-hero-video {
  display: block;
  width: 100%;
  aspect-ratio: 16/9;
  border: 0;
  border-radius: 18px;
  box-shadow: 0 24px 60px rgba(28, 69, 126, 0.18);
}

.wms-product-visual .wms-product-frame, .wms-product-visual .wms-connectors {
  display: none;
}

.wms-video-preview {
  position: relative;
  display: flex;
  align-items: flex-end;
  width: 100%;
  max-width: 640px;
  aspect-ratio: 16/9;
  margin-left: auto;
  padding: 24px;
  overflow: hidden;
  border: 1px solid rgba(255, 255, 255, 0.24);
  border-radius: 22px;
  color: #fff;
  text-align: left;
  cursor: pointer;
  background-color: #07132f;
  background-position: center;
  background-size: cover;
  box-shadow: 0 24px 60px rgba(28, 69, 126, 0.18);
  transition: transform 0.2s ease, box-shadow 0.2s ease;
}

.wms-video-preview::before {
  content: "";
  position: absolute;
  inset: 0;
  background: linear-gradient(135deg, rgba(4, 13, 35, 0.2), rgba(4, 13, 35, 0.88));
}

.wms-video-preview:hover {
  transform: translateY(-2px);
  box-shadow: 0 28px 70px rgba(28, 69, 126, 0.3);
}

.wms-video-preview:focus {
  outline: 2px solid #007bff;
  outline-offset: 3px;
}

.wms-video-preview-play {
  position: absolute;
  inset: 0;
  display: flex;
  align-items: center;
  justify-content: center;
}

.wms-video-preview-play i {
  display: flex;
  align-items: center;
  justify-content: center;
  width: 64px;
  height: 64px;
  padding-left: 4px;
  border-radius: 50%;
  color: #007bff;
  background: #fff;
  box-shadow: 0 12px 28px rgba(0, 0, 0, 0.28);
  font-size: 24px;
}

.wms-video-preview-copy {
  position: relative;
  max-width: 360px;
}

.wms-video-preview-copy small {
  display: block;
  color: rgba(255, 255, 255, 0.7);
  font-size: 11px;
  font-weight: 700;
  letter-spacing: 0.18em;
  text-transform: uppercase;
}

.wms-video-preview-copy strong {
  display: block;
  margin-top: 8px;
  font-size: 24px;
  line-height: 1.2;
}

/* ── Compact sections ───────────────────────────────── */
.wms-compact-section {
  padding: 20px 28px;
}

.wms-compact-heading {
  font-family: "Delivery", sans-serif;
  font-size: 11px;
  font-weight: 700;
  text-transform: uppercase;
  letter-spacing: 0.06em;
  color: #999;
  margin: 0 0 10px;
}

/* ── Why use WMS (3 horizontal cards) ───────────────── */
.wms-why-grid {
  display: grid;
  grid-template-columns: repeat(3, 1fr);
  gap: 10px;
}
@media (max-width: 768px) {
  .wms-why-grid {
    grid-template-columns: 1fr;
  }
}

.wms-why-card {
  display: flex;
  align-items: flex-start;
  gap: 10px;
  background: #FFFFFF;
  border: 1px solid #B8B8B8;
  border-radius: 8px;
  padding: 12px;
}
.wms-why-card .wms-why-icon {
  width: 32px;
  height: 32px;
  background: #e7f1fe;
  border-radius: 6px;
  display: flex;
  align-items: center;
  justify-content: center;
  flex-shrink: 0;
}
.wms-why-card .wms-why-icon i {
  font-size: 14px;
  color: #007bff;
}
.wms-why-card h4 {
  font-family: "Delivery", sans-serif;
  font-size: 13px;
  font-weight: 600;
  color: #333333;
  margin: 0 0 2px;
  line-height: 1.3;
}
.wms-why-card p {
  font-family: "Delivery", sans-serif;
  font-size: 11px;
  line-height: 1.45;
  color: #5b5b5b;
  margin: 0;
}

/* ── What's included (compact 8-col grid) ───────────── */
.wms-capabilities-grid {
  display: grid;
  grid-template-columns: repeat(8, 1fr);
  gap: 6px;
}
@media (max-width: 768px) {
  .wms-capabilities-grid {
    grid-template-columns: repeat(4, 1fr);
  }
}

.wms-capability-item {
  display: flex;
  flex-direction: column;
  align-items: center;
  gap: 4px;
  padding: 10px 4px;
  background: #FFFFFF;
  border: 1px solid #B8B8B8;
  border-radius: 6px;
  text-align: center;
}
.wms-capability-item i {
  font-size: 14px;
  color: #007bff;
}
.wms-capability-item span {
  font-family: "Delivery", sans-serif;
  font-size: 10px;
  font-weight: 600;
  color: #333;
  line-height: 1.2;
}

/* ── CTA decision cards ─────────────────────────────── */
.wms-decision-grid {
  display: grid;
  grid-template-columns: repeat(2, 1fr);
  gap: 10px;
  padding: 0 28px 20px;
}
@media (max-width: 576px) {
  .wms-decision-grid {
    grid-template-columns: 1fr;
  }
}

.wms-decision-card {
  border: 1px solid #B8B8B8;
  border-radius: 8px;
  padding: 14px;
}
.wms-decision-card .wms-decision-header {
  display: flex;
  align-items: center;
  gap: 8px;
  margin-bottom: 6px;
}
.wms-decision-card .wms-decision-header i {
  font-size: 14px;
  color: #999;
}
.wms-decision-card .wms-decision-header span {
  font-family: "Delivery", sans-serif;
  font-size: 13px;
  font-weight: 600;
  color: #333;
}
.wms-decision-card p {
  font-family: "Delivery", sans-serif;
  font-size: 11px;
  color: #5b5b5b;
  margin: 0 0 10px;
  line-height: 1.45;
}
.wms-decision-card.wms-decision-primary {
  border: 2px solid #007bff;
  background: rgba(0, 123, 255, 0.02);
}
.wms-decision-card.wms-decision-primary .wms-decision-header i {
  color: #007bff;
}

/* ── FAQ (collapsed wrapper) ────────────────────────── */
.wms-faq-wrapper {
  padding: 0 28px 20px;
}

.wms-faq-toggle {
  width: 100%;
  display: flex;
  align-items: center;
  justify-content: space-between;
  padding: 8px 0;
  background: none;
  border: none;
  cursor: pointer;
}
.wms-faq-toggle i {
  font-size: 11px;
  color: #999;
}
.wms-faq-toggle:hover {
  opacity: 0.8;
}

.wms-faq-container {
  border: 1px solid #B8B8B8;
  border-radius: 8px;
  overflow: hidden;
  background: #FFFFFF;
  margin-top: 6px;
}

.wms-faq-item {
  border-bottom: 1px solid #B8B8B8;
}
.wms-faq-item:last-child {
  border-bottom: none;
}

.wms-faq-trigger {
  width: 100%;
  display: flex;
  align-items: center;
  justify-content: space-between;
  padding: 10px 14px;
  background: none;
  border: none;
  cursor: pointer;
  text-align: left;
  font-family: "Delivery", sans-serif;
  font-size: 13px;
  font-weight: 600;
  color: #333;
}
.wms-faq-trigger:hover {
  background: #fafafa;
}
.wms-faq-trigger i {
  font-size: 10px;
  color: #999;
  flex-shrink: 0;
  margin-left: 10px;
}

.wms-faq-answer {
  padding: 0 14px 10px;
}
.wms-faq-answer p {
  font-family: "Delivery", sans-serif;
  font-size: 12px;
  line-height: 1.55;
  color: #5b5b5b;
  margin: 0;
}

/* ── Success / Error ────────────────────────────────── */
.wms-cta-success {
  display: inline-flex;
  align-items: center;
  gap: 10px;
  margin-top: 16px;
  padding: 12px 18px;
  background: rgba(0, 101, 47, 0.08);
  border: 1px solid rgba(0, 101, 47, 0.25);
  border-radius: 8px;
  color: #00652F;
  font-family: "Delivery", sans-serif;
  font-size: 13px;
}
.wms-cta-success i {
  font-size: 16px;
}
.wms-cta-success strong {
  display: block;
}
.wms-cta-success small {
  opacity: 0.85;
}

.wms-cta-error {
  display: inline-flex;
  align-items: center;
  gap: 8px;
  margin-top: 16px;
  padding: 10px 16px;
  background: #FCEBEA;
  border: 1px solid rgba(185, 28, 28, 0.3);
  border-radius: 8px;
  color: #B91C1C;
  font-family: "Delivery", sans-serif;
  font-size: 13px;
}
.wms-cta-error i {
  font-size: 14px;
}

/* ── Modals ─────────────────────────────────────────── */
.wms-modal-backdrop {
  position: fixed;
  top: 0;
  left: 0;
  right: 0;
  bottom: 0;
  background: rgba(0, 0, 0, 0.6);
  display: flex;
  align-items: center;
  justify-content: center;
  z-index: 10000;
  padding: 20px;
  animation: wms-fade-in 0.15s ease;
}

@keyframes wms-fade-in {
  from {
    opacity: 0;
  }
  to {
    opacity: 1;
  }
}
.wms-modal {
  background: #FFFFFF;
  border-radius: 10px;
  width: 100%;
  max-width: 440px;
  max-height: 90vh;
  display: flex;
  flex-direction: column;
  box-shadow: 0 8px 32px rgba(0, 0, 0, 0.2);
  animation: wms-scale-in 0.15s ease;
  overflow: hidden;
}

@keyframes wms-scale-in {
  from {
    transform: scale(0.96);
    opacity: 0;
  }
  to {
    transform: scale(1);
    opacity: 1;
  }
}
.wms-modal-header {
  display: flex;
  align-items: center;
  justify-content: space-between;
  padding: 16px 20px;
  border-bottom: 1px solid #B8B8B8;
}

.wms-modal-title {
  font-family: "Delivery", sans-serif;
  font-size: 16px;
  font-weight: 600;
  color: #333;
}

.wms-modal-close {
  background: none;
  border: none;
  padding: 6px;
  cursor: pointer;
  color: #999;
  border-radius: 4px;
}
.wms-modal-close:hover {
  color: #333;
  background: #f0f0f0;
}
.wms-modal-close i {
  font-size: 16px;
}

.wms-modal-body {
  display: block;
  min-width: 0;
  padding: 16px 20px;
  overflow-y: auto;
}

.wms-video-modal {
  width: calc(100vw - 40px);
  max-width: none;
  height: calc(100vh - 40px);
  max-height: calc(100dvh - 40px);
  background: #07132f;
  color: #fff;
}

.wms-video-modal .wms-modal-header {
  border-bottom-color: rgba(255, 255, 255, 0.14);
}

.wms-video-modal .wms-modal-title {
  color: #fff;
}

.wms-video-modal .wms-modal-close {
  color: rgba(255, 255, 255, 0.7);
}

.wms-video-modal .wms-modal-close:hover {
  color: #fff;
  background: rgba(255, 255, 255, 0.1);
}

.wms-video-modal .wms-modal-body {
  display: flex;
  flex: 1 1 auto;
  flex-direction: column;
  min-height: 0;
}

.wms-video-frame {
  position: relative;
  flex: 1 1 auto;
  min-height: 0;
  overflow: hidden;
  border-radius: 10px;
  background: #000;
}

.wms-video-frame iframe {
  position: absolute;
  inset: 0;
  width: 100%;
  height: 100%;
  border: 0;
}

.wms-video-modal-links {
  display: flex;
  flex-wrap: wrap;
  align-items: center;
  justify-content: center;
  width: 100%;
  flex: 0 0 auto;
  gap: 16px;
  margin-top: 24px;
  padding: 0 12px 8px;
}

.wms-video-modal-link {
  display: inline-flex;
  align-items: center;
  justify-content: center;
  gap: 6px;
  min-height: 44px;
  padding: 12px 18px;
  border: 1px solid rgba(76, 163, 255, 0.85);
  border-radius: 8px;
  color: #fff;
  background: #123a70;
  font-size: 13px;
  font-weight: 600;
  text-decoration: none;
}

.wms-video-modal-link:last-child {
  border-color: #2f80ff;
  background: #2f80ff;
}

.wms-video-modal-link:hover {
  color: #fff;
  background: #1a4c8d;
}

.wms-video-modal-link:last-child:hover {
  background: #1b6fe5;
}

.wms-modal-footer {
  display: flex;
  align-items: center;
  justify-content: flex-end;
  gap: 8px;
  margin-top: 16px;
  padding-top: 14px;
  border-top: 1px solid #B8B8B8;
}

.wms-modal-loading {
  display: flex;
  align-items: center;
  justify-content: center;
  gap: 10px;
  padding: 36px 0;
  font-family: "Delivery", sans-serif;
  font-size: 14px;
  color: #999;
}

@media (max-width: 640px) {
  .wms-modal-backdrop {
    padding: 12px;
  }
  .wms-modal-header {
    padding: 12px 14px;
  }
  .wms-modal-body {
    padding: 12px 14px;
  }
  .wms-video-modal {
    width: calc(100vw - 24px);
    height: calc(100vh - 24px);
    max-height: calc(100dvh - 24px);
  }
  .wms-video-modal .wms-modal-body {
    padding: 12px;
  }
  .wms-video-preview {
    padding: 16px;
    border-radius: 16px;
  }
  .wms-video-preview-copy strong {
    font-size: 20px;
  }
  .wms-video-modal-links {
    flex-direction: column;
    gap: 12px;
  }
  .wms-video-modal-link {
    width: 100%;
  }
}
/* Trial details */
.wms-trial-details {
  background: #f8f9fa;
  border: 1px solid #B8B8B8;
  border-radius: 8px;
  padding: 14px;
  margin-bottom: 14px;
}

.wms-trial-row {
  display: flex;
  align-items: center;
  justify-content: space-between;
  padding: 4px 0;
  font-family: "Delivery", sans-serif;
  font-size: 13px;
  color: #5b5b5b;
}
.wms-trial-row strong {
  color: #333;
}

.wms-trial-next {
  background: #f8f9fa;
  border: 1px solid #B8B8B8;
  border-radius: 8px;
  padding: 14px;
}
.wms-trial-next strong {
  font-family: "Delivery", sans-serif;
  font-size: 13px;
  color: #333;
  display: block;
  margin-bottom: 6px;
}
.wms-trial-next ul {
  list-style: none;
  padding: 0;
  margin: 0;
}
.wms-trial-next ul li {
  font-family: "Delivery", sans-serif;
  font-size: 13px;
  color: #5b5b5b;
  line-height: 1.6;
}

/* ── Responsive ─────────────────────────────────────── */
@media (max-width: 768px) {
  .wms-hero-section {
    padding: 20px;
  }
  .wms-hero-copy .wms-hero-title {
    font-size: 20px;
  }
}
/* ── Approved product-led landing page ──────────────────────── */
.warehouse-management-page .page-main-content.wms-marketing {
  background: #ffffff;
  color: #14213d;
}

.wms-hero-section {
  background: #f2f7ff;
  color: #14213d;
  padding: 46px clamp(24px, 5vw, 72px) 52px;
}

.wms-hero-grid {
  max-width: 1240px;
  margin: 0 auto;
  grid-template-columns: minmax(0, 0.92fr) minmax(0, 1.08fr);
  gap: clamp(32px, 5vw, 72px);
}

.wms-badge {
  background: rgba(255, 255, 255, 0.8);
  border-color: rgba(0, 123, 255, 0.3);
  color: #006ee3;
  padding: 5px 11px;
  margin-bottom: 14px;
}

.wms-hero-copy .wms-hero-title {
  max-width: 620px;
  color: #14213d;
  font-size: clamp(32px, 4vw, 52px);
  line-height: 1.08;
  letter-spacing: -1.2px;
}

.wms-hero-copy .wms-hero-subtitle {
  max-width: 580px;
  color: #52627a;
  font-size: 15px;
  line-height: 1.7;
  opacity: 1;
}

.wms-hero-copy {
  display: flex;
  flex-direction: column;
  align-items: flex-start;
}

.wms-hero-ctas {
  gap: 10px;
  margin-top: 2px;
}

.wms-btn-primary {
  background: #007bff;
  box-shadow: 0 8px 18px rgba(0, 123, 255, 0.18);
}

.wms-btn-primary:hover:not(:disabled) {
  background: #006ee3;
}

.wms-btn-ghost, .wms-btn-outline {
  color: #14213d;
  border: 1px solid #b9c9df;
  background: rgba(255, 255, 255, 0.6);
}

.wms-btn-ghost:hover:not(:disabled), .wms-btn-outline:hover:not(:disabled) {
  color: #006ee3;
  background: #ffffff;
}

.wms-text-link {
  display: inline-flex;
  align-items: center;
  gap: 6px;
  margin-top: 14px;
  padding: 0;
  border: 0;
  background: transparent;
  font-family: inherit;
  text-align: left;
  color: #006ee3;
  font-size: 13px;
  font-weight: 600;
  text-decoration: underline;
  text-underline-offset: 3px;
}

.wms-text-link:focus {
  outline: 2px solid #006ee3;
  outline-offset: 3px;
}

.wms-hero-fine-print {
  margin-top: 14px;
  color: #52627a;
  opacity: 1;
  font-size: 12px;
}

.wms-trust-line {
  display: flex;
  flex-wrap: wrap;
  gap: 8px 18px;
  width: 100%;
  margin-top: 18px;
  padding-top: 15px;
  border-top: 1px solid rgba(0, 123, 255, 0.14);
  color: #52627a;
  font-size: 12px;
}

.wms-product-visual {
  position: relative;
  max-width: 640px;
  margin-left: auto;
}

.wms-product-frame {
  position: relative;
  padding: 12px;
  border: 1px solid #d7e2f1;
  border-radius: 22px;
  background: #fff;
  box-shadow: 0 24px 60px rgba(28, 69, 126, 0.18);
}

.wms-product-shell {
  padding: 16px;
  border-radius: 15px;
  background: #13213d;
  color: #fff;
}

.wms-product-topbar {
  display: flex;
  justify-content: space-between;
  padding-bottom: 12px;
  border-bottom: 1px solid rgba(255, 255, 255, 0.1);
  font-size: 10px;
}

.wms-product-topbar span:last-child {
  padding: 5px 9px;
  border-radius: 999px;
  background: rgba(255, 255, 255, 0.1);
  color: rgba(255, 255, 255, 0.7);
}

.wms-product-stats {
  display: grid;
  grid-template-columns: repeat(4, 1fr);
  gap: 8px;
  margin-top: 12px;
}

.wms-product-stat {
  padding: 10px;
  border-radius: 8px;
  background: rgba(255, 255, 255, 0.08);
}

.wms-product-stat small {
  display: block;
  color: rgba(255, 255, 255, 0.55);
  font-size: 8px;
}

.wms-product-stat strong {
  display: block;
  margin-top: 4px;
  font-size: 15px;
}

.wms-product-body {
  display: grid;
  grid-template-columns: 1.18fr 0.82fr;
  gap: 8px;
  margin-top: 8px;
}

.wms-stock-panel, .wms-pack-panel {
  padding: 12px;
  border-radius: 8px;
  color: #3d4d64;
  background: #fff;
}

.wms-pack-panel {
  background: #e8f1ff;
}

.wms-stock-heading {
  display: flex;
  justify-content: space-between;
  font-size: 9px;
  font-weight: 700;
}

.wms-stock-heading span:last-child {
  color: #007bff;
}

.wms-stock-row {
  display: flex;
  align-items: center;
  gap: 8px;
  padding: 8px 0;
  border-bottom: 1px solid #edf1f6;
  font-size: 9px;
}

.wms-stock-row:last-child {
  border-bottom: 0;
  padding-bottom: 0;
}

.wms-stock-thumb {
  width: 24px;
  height: 24px;
  flex: 0 0 24px;
  border-radius: 6px;
  background: #e8f1ff;
}

.wms-stock-copy {
  min-width: 0;
  flex: 1;
}

.wms-stock-copy strong, .wms-stock-copy small {
  display: block;
}

.wms-stock-copy strong {
  overflow: hidden;
  text-overflow: ellipsis;
  white-space: nowrap;
}

.wms-stock-copy small {
  color: #91a0b4;
}

.wms-stock-status {
  color: #159570;
  font-size: 8px;
  font-weight: 700;
}

.wms-stock-status.low {
  color: #c38311;
}

.wms-pack-heading {
  display: flex;
  align-items: center;
  gap: 6px;
  font-size: 9px;
  font-weight: 700;
}

.wms-pack-heading i, .wms-connector i {
  color: #007bff;
}

.wms-pack-progress {
  margin-top: 17px;
  font-size: 26px;
  font-weight: 700;
  color: #14213d;
}

.wms-pack-bar {
  height: 6px;
  margin-top: 6px;
  border-radius: 99px;
  background: #fff;
  overflow: hidden;
}

.wms-pack-bar span {
  display: block;
  width: 78%;
  height: 100%;
  border-radius: inherit;
  background: #007bff;
}

.wms-pack-panel small {
  display: block;
  margin-top: 8px;
  color: #687990;
  font-size: 8px;
}

.wms-connectors {
  display: flex;
  align-items: center;
  justify-content: center;
  flex-wrap: wrap;
  gap: 10px;
  margin-top: -1px;
  color: #52627a;
  font-size: 9px;
  font-weight: 700;
}

.wms-connector {
  display: inline-flex;
  align-items: center;
  gap: 4px;
}

.wms-connector-line {
  width: 28px;
  height: 1px;
  background: rgba(0, 123, 255, 0.3);
}

.wms-page-section {
  padding: 54px clamp(24px, 5vw, 72px);
}

.wms-section-inner {
  max-width: 1240px;
  margin: 0 auto;
}

.wms-benefits-section {
  background: #fff;
}

.wms-section-title {
  margin: 0;
  color: #14213d;
  text-align: center;
  font-size: 30px;
  line-height: 1.2;
  letter-spacing: -0.5px;
}

.wms-benefit-grid {
  display: grid;
  grid-template-columns: repeat(3, 1fr);
  gap: 32px;
  margin-top: 38px;
}

.wms-benefit-card {
  text-align: center;
}

.wms-benefit-icon {
  display: flex;
  align-items: center;
  justify-content: center;
  width: 48px;
  height: 48px;
  margin: 0 auto 15px;
  border-radius: 16px;
  color: #007bff;
  background: #e8f1ff;
  font-size: 22px;
}

.wms-benefit-card h3 {
  margin: 0;
  color: #14213d;
  font-size: 16px;
  line-height: 1.35;
}

.wms-benefit-card p {
  max-width: 320px;
  margin: 9px auto 0;
  color: #52627a;
  font-size: 13px;
  line-height: 1.7;
}

.wms-pricing-proof {
  display: flex;
  align-items: center;
  flex-wrap: wrap;
  gap: 16px 22px;
  max-width: 560px;
  margin-top: 18px;
  padding: 12px 16px;
  border: 1px solid rgba(0, 123, 255, 0.15);
  border-radius: 10px;
  color: #52627a;
  background: rgba(255, 255, 255, 0.7);
}

.wms-pricing-proof strong, .wms-pricing-proof small {
  display: block;
}

.wms-pricing-proof strong {
  color: #14213d;
  font-size: 18px;
  line-height: 1.1;
}

.wms-pricing-proof small {
  margin-top: 4px;
  color: #687990;
  font-size: 11px;
}

.wms-pricing-proof > span {
  max-width: 300px;
  font-size: 12px;
  font-weight: 600;
  line-height: 1.55;
}

.wms-testimonial {
  min-width: 0;
  padding: 24px;
  border-radius: 16px;
  color: #14213d;
  background: #fff;
  box-shadow: 0 18px 50px rgba(4, 13, 35, 0.18);
}

.wms-testimonial-logo {
  display: block;
  width: 144px;
  height: auto;
  margin-bottom: 20px;
  object-fit: contain;
  object-position: left;
}

.wms-testimonial blockquote {
  margin: 0;
  font-size: 15px;
  font-weight: 600;
  line-height: 1.7;
}

.wms-testimonial figcaption {
  margin-top: 16px;
  color: #52627a;
  font-size: 11px;
  font-weight: 700;
  letter-spacing: 0.12em;
  text-transform: uppercase;
}

.wms-overview-section {
  display: grid;
  grid-template-columns: 1.05fr 0.95fr;
  align-items: center;
  gap: 48px;
  background: #fff;
}

.wms-overview-video {
  position: relative;
  aspect-ratio: 16/9;
  overflow: hidden;
  border: 1px solid #d7e2f1;
  border-radius: 12px;
  background: #13213d;
  box-shadow: 0 14px 30px rgba(28, 69, 126, 0.14);
}

.wms-overview-video iframe {
  position: absolute;
  inset: 0;
  width: 100%;
  height: 100%;
  border: 0;
}

.wms-overview-copy .wms-eyebrow {
  margin: 0 0 10px;
  color: #007bff;
  font-size: 11px;
  font-weight: 700;
  letter-spacing: 0.18em;
  text-transform: uppercase;
}

.wms-overview-copy h2 {
  margin: 0;
  color: #14213d;
  font-size: 30px;
  line-height: 1.2;
}

.wms-overview-copy p {
  margin: 14px 0 20px;
  color: #52627a;
  font-size: 14px;
  line-height: 1.7;
}

.wms-closing-section {
  padding: 36px clamp(24px, 5vw, 72px);
  color: #fff;
  background: #007bff;
}

.wms-closing-section .wms-section-inner {
  display: grid;
  grid-template-columns: minmax(0, 1fr) minmax(320px, 0.82fr);
  align-items: center;
  gap: 48px;
  width: 100%;
}

.wms-closing-copy {
  max-width: 700px;
}

.wms-closing-copy h2 {
  margin: 0;
  color: #fff;
  font-size: 30px;
  line-height: 1.2;
}

.wms-closing-copy p {
  margin: 10px 0 0;
  color: rgba(255, 255, 255, 0.82);
  font-size: 14px;
  line-height: 1.7;
}

.wms-closing-actions {
  display: flex;
  flex-wrap: wrap;
  gap: 10px;
  margin-top: 20px;
}

.wms-closing-actions .wms-btn-primary {
  color: #007bff;
  background: #fff;
  box-shadow: none;
}

.wms-closing-actions .wms-btn-outline {
  color: #fff;
  border-color: rgba(255, 255, 255, 0.5);
  background: transparent;
}

.wms-closing-actions .wms-btn-outline:hover {
  color: #fff;
  background: rgba(255, 255, 255, 0.1);
}

@media (max-width: 900px) {
  .wms-hero-grid, .wms-overview-section {
    grid-template-columns: 1fr;
  }
  .wms-product-visual {
    margin: 0 auto;
  }
  .wms-closing-section .wms-section-inner {
    grid-template-columns: 1fr;
  }
}
@media (max-width: 640px) {
  .wms-hero-section {
    padding: 34px 20px 40px;
  }
  .wms-page-section {
    padding: 40px 20px;
  }
  .wms-hero-copy .wms-hero-title {
    font-size: 34px;
  }
  .wms-product-shell {
    padding: 10px;
  }
  .wms-product-body {
    grid-template-columns: 1fr;
  }
  .wms-product-stats {
    gap: 4px;
  }
  .wms-product-stat {
    padding: 7px 5px;
  }
  .wms-product-stat strong {
    font-size: 12px;
  }
  .wms-benefit-grid {
    grid-template-columns: 1fr;
    gap: 28px;
  }
  .wms-testimonial {
    padding: 20px;
  }
  .wms-testimonial blockquote {
    font-size: 14px;
  }
  .wms-closing-section {
    padding: 32px 20px;
  }
}
